import{_ as t,o as e,c as a,a2 as d}from"./chunks/framework.DGk0zlJw.js";const p=JSON.parse('{"title":"故障排查（FAQ）","description":"","frontmatter":{},"headers":[],"relativePath":"zh/troubleshooting.md","filePath":"zh/troubleshooting.md"}'),r={name:"zh/troubleshooting.md"};function i(n,o,l,c,s,h){return e(),a("div",null,[...o[0]||(o[0]=[d('<h1 id="故障排查-faq" tabindex="-1">故障排查（FAQ） <a class="header-anchor" href="#故障排查-faq" aria-label="Permalink to &quot;故障排查（FAQ）&quot;">​</a></h1><blockquote><p>安装与启动问题的排查手册。配合 <a href="https://github.com/cuihairu/beacon#download" target="_blank" rel="noreferrer">README 下载节</a> 与 <a href="./acceptance-B803-e2e-walkthrough.html">B-803 端到端走查</a> 使用。</p></blockquote><h2 id="双击没反应" tabindex="-1">双击没反应？ <a class="header-anchor" href="#双击没反应" aria-label="Permalink to &quot;双击没反应？&quot;">​</a></h2><p>Beacon 是<strong>托盘常驻应用，没有主窗口</strong>——启动成功的可见形态是：屏幕右下角状态胶囊 + 启动通知气泡 + 托盘图标（红圈 b）。三者皆无才按下面顺序排查：</p><ol><li><strong>SmartScreen 拦截</strong>：未签名 exe 首次运行会被拦——点「更多信息」→「仍要运行」。</li><li><strong>确认进程在不在</strong>：任务管理器搜 <code>Beacon.App</code>。在而看不见胶囊 → 记下日志后提 Issue。</li><li><strong>查日志</strong>：<code>%AppData%\\Beacon\\logs\\beacon-*.log</code>（运行日志，按天滚动）。</li><li><strong>启动失败弹窗 / crash 日志</strong>：启动阶段出错会<strong>弹错误框</strong>（含堆栈与日志路径），同时落盘 <code>%AppData%\\Beacon\\logs\\crash-*.log</code>——把弹窗截图或日志内容提 Issue 即可定位。</li></ol><h2 id="升级后行为没变" tabindex="-1">升级后行为没变？ <a class="header-anchor" href="#升级后行为没变" aria-label="Permalink to &quot;升级后行为没变？&quot;">​</a></h2><p>Beacon 是<strong>单实例常驻</strong>：安装器覆盖了文件，但托盘里驻留的还是旧进程，二次启动只会通知旧实例——「更新了还是老样子」多半是这个。</p><ol><li>托盘图标右键 → <strong>Exit</strong>（唯一退出路径），再重新启动；</li><li>设置 → 常规底部看 <strong>版本行</strong>：nightly 形如 <code>2026.10.9+&lt;完整 commit sha&gt;</code>（<code>yyyy.M.d</code> 四段日期，取自构建当天 + publish 时的 <code>GITHUB_SHA</code>；早先的 <code>0.0.yyyyMMdd</code> 形态会触发 CS7034，已改），对一下构建日期；</li><li>版本行还是旧的 = 没装上新包（重新下载 nightly 资产，见下方校验）。</li></ol><h2 id="便携-zip-校验" tabindex="-1">便携 zip 校验 <a class="header-anchor" href="#便携-zip-校验" aria-label="Permalink to &quot;便携 zip 校验&quot;">​</a></h2><p><code>Get-FileHash beacon-nightly-windows-x86_64.zip -Algorithm SHA256</code> 与 Release 内 <code>SHA256SUMS</code> 逐行比对；装了 Git Bash 也可 <code>sha256sum -c SHA256SUMS</code>。</p><p>解压后直接运行 <code>Beacon.App.exe</code>——自包含包，无需安装 .NET 运行时，也无需 VC++ 运行库（发布产物实测仅依赖系统自带组件）。</p><h2 id="安装包" tabindex="-1">安装包 <a class="header-anchor" href="#安装包" aria-label="Permalink to &quot;安装包&quot;">​</a></h2><p>装到 <code>%LOCALAPPDATA%\\Beacon</code>（无需管理员），开始菜单启动，卸载走系统「添加或删除程序」。安装向导全程简体中文。</p><p>安装器复选框/文字显示异常（溢出、看不清）多半是旧版构建—— nightly 滚动更新，重新下载最新 <code>setup.exe</code> 即可。</p><h2 id="组件不出数-白板排查" tabindex="-1">组件不出数（白板排查） <a class="header-anchor" href="#组件不出数-白板排查" aria-label="Permalink to &quot;组件不出数（白板排查）&quot;">​</a></h2><p>「一键添加」「组件向导」添加的组件<strong>应当几秒内上板出数</strong>（添加即钉选、即拉取，无需强刷/重启）。若板面空白，按跳排查（每跳在运行日志里都有一行）：</p><table tabindex="0"><thead><tr><th>跳</th><th>日志关键词</th><th>空白时的含义</th></tr></thead><tbody><tr><td>① 组件创建</td><td><code>一键示例：组件 … 已创建并钉选</code></td><td>没有这行 = 添加动作没发生（连接缺失会红字提示）</td></tr><tr><td>② 注册+首拉</td><td><code>组件注册已重建并立即拉取 N 个</code></td><td>没有这行 = 调度器没接到新组件（旧版本 bug，升级 nightly）</td></tr><tr><td>③ 拉取结果</td><td><code>Widget … refreshed ok: …</code>（成功）/ <code>refresh failed: …</code>（失败带原因）</td><td>失败原因直显在 tile 值位（「拉取失败：…」）——网络/TLS/401/字段映射一目了然</td></tr><tr><td>④ 渲染</td><td>tile 灰灯+「加载中…」→ 有数后变级色</td><td>恒为「加载中…」= ③一直在失败；看失败原因行</td></tr></tbody></table><p>另查两处：组件列表（设置 → 对应模块）里该组件是否带「已钉」标记；<code>组件不出数且日志全无</code> → 确认模块开关（左侧目录）是开的——停用模块的组件不占板面。</p><h2 id="小米-mimo-卡显示-offline-不出数" tabindex="-1">小米 MiMo 卡显示 Offline / 不出数？ <a class="header-anchor" href="#小米-mimo-卡显示-offline-不出数" aria-label="Permalink to &quot;小米 MiMo 卡显示 Offline / 不出数？&quot;">​</a></h2><p>先分清两件事：<strong>胶囊上的「Offline」横幅是聚合告警</strong>——任何连接不健康（含 Degraded）都会点亮它；真正的失败原因在 <strong>tile 值位</strong>（「拉取失败：…」）和运行日志的 <code>refresh failed</code> 行。MiMo 常见三种：</p><ol><li><strong>「控制台 Cookie 已失效或未录制」</strong>：额度卡的登录态过期（会话 cookie 过期是常态）。重录：浏览器登录 <code>platform.xiaomimimo.com</code> → F12 → 应用 → Cookies → 复制 <code>api-platform_ph</code> 的值 → 设置 → 小米模块连接里粘贴（整行 Cookie 粘进来也行，会自动取该键）。</li><li><strong>只填了 API Key</strong>：Key 只授权模型调用（<code>/v1/models</code> 连接测试绿≠Cookie 有效，两条凭据链），<strong>额度必须另录控制台 Cookie</strong>——Bearer/裸头带 Key 实测全 401。</li><li><strong>LiteLLM 网关记账档</strong>：连接 Settings <code>litellm_spend_url</code> <strong>默认空=不外发（正常，不是故障）</strong>；填了但卡面显「未接数据库」= 你本机 LiteLLM 网关 config 没接 database——spend 面全回 <code>no_db_connection</code>，需网关侧接 DB（SQLite 即可）后自动出「本月已用 $X」。</li></ol><h2 id="悬浮框白板残留-品牌-icon-不显示" tabindex="-1">悬浮框白板残留 / 品牌 icon 不显示 <a class="header-anchor" href="#悬浮框白板残留-品牌-icon-不显示" aria-label="Permalink to &quot;悬浮框白板残留 / 品牌 icon 不显示&quot;">​</a></h2><ul><li><strong>全局关「数量悬浮窗」后桌面还剩一个白板空窗</strong>：旧版悬浮窗关闭只调 WinUI <code>Window.Close</code>，在无边框 NOACTIVATE 窗上不保证销毁窗口句柄——内容已拆、壳残留即白板。已修（Close 后句柄仍存活则硬销毁）；升级 nightly 后须托盘 Exit 重启（单实例常驻）。再出现即新问题，附运行日志反馈。</li><li><strong>悬浮框/设置目录里的品牌 icon 不显示（只剩灯+文字）</strong>：旧版 <code>Viewbox(PathIcon)</code> 组合在 WinUI 3 下量测为空、渲染成空白且挡掉兜底字形。已修（改 Path 形状直渲 + 空几何退兜底）。</li><li><strong>两态截图证据</strong>：daily-build 每个 run 的 artifact「visual-evidence」——数量悬浮窗开 = 悬浮框全屏+icon 六倍近景；关 = 桌面零残留窗（附硬断言，回归即红构建）。</li></ul><h2 id="dsl-声明文件-dsl-path-报错" tabindex="-1">DSL 声明文件（dsl_path）报错？ <a class="header-anchor" href="#dsl-声明文件-dsl-path-报错" aria-label="Permalink to &quot;DSL 声明文件（dsl_path）报错？&quot;">​</a></h2><p>http 连接 Settings 配了 <code>dsl_path</code> 后，声明文件的问题<strong>不会静默</strong>：相关卡面直接 Degraded 并带原因（启动与其他连接不受影响；声明动作加载失败只记运行日志）。常见三种：</p><ol><li><strong>「DSL 文件不存在」</strong>：Settings 里的路径写错或文件被移走。核对绝对路径（含盘符/用户名），改完等下次刷新即恢复。</li><li><strong>「DSL 文件解析失败（第 N 行：…）」</strong>：解析器只支持 YAML 子集，常见踩点——缩进用了 <strong>Tab</strong>（只许空格）；JSON 字面量没加引号（<code>body: {&quot;a&quot;:1}</code> 要写成 <code>body: &#39;{&quot;a&quot;:1}&#39;</code>，裸 <code>{}</code>/<code>[]</code> 按不支持语法拒绝）；引号未闭合；mapping 用了白名单外的键（拼错即报，不静默忽略）；列表项必须是 <code>- key: value</code>（不支持纯标量列表/多文档 <code>---</code>）。按行号改即可，语法参考 <code>configuration.md</code>「Provider DSL」节。</li><li><strong>改了文件没生效</strong>：文件按 mtime+大小缓存，保存后（编辑器真的写盘）下次刷新自动重解析；若编辑器「保存」没改 mtime，随手再刷新一次或托盘 Refresh All。</li></ol><h2 id="日志一览" tabindex="-1">日志一览 <a class="header-anchor" href="#日志一览" aria-label="Permalink to &quot;日志一览&quot;">​</a></h2><table tabindex="0"><thead><tr><th>日志</th><th>位置</th><th>内容</th></tr></thead><tbody><tr><td>运行日志</td><td><code>%AppData%\\Beacon\\logs\\beacon-YYYYMMDD.log</code></td><td>刷新/通知/动作执行 + 组件管线逐跳诊断，按天滚动</td></tr><tr><td>崩溃日志</td><td><code>%AppData%\\Beacon\\logs\\crash-*.log</code></td><td>启动与运行期未处理异常堆栈</td></tr><tr><td>配置</td><td><code>%AppData%\\Beacon\\config.json</code> 等</td><td>连接/组件/钉选/外观（token 只存 credentialRef，绝不落明文）</td></tr></tbody></table>',28)])])}const u=t(r,[["render",i]]);export{p as __pageData,u as default};
